function securityRlsInputSanitizationBoundaryMapUnsafeFlags() {
  return Object.fromEntries(
    SECURITY_RLS_INPUT_SANITIZATION_BOUNDARY_UNSAFE_FIELDS.map((field) => [
      field,
      false
    ])
  );
}

